// Map uniform random numbers to $[-1,1]^2$ and handle special cases
Float sx = 2 * u[0] - 1;
Float sy = 2 * u[1] - 1;

// Handle degeneracy at the origin
if (sx == 0 && sy == 0) return Point2f(0, 0);

// Apply concentric mapping
Float theta, r;
if (std::abs(sx) > std::abs(sy)) {
    r = sx;
    theta = sy / (sx * 4);
} else {
    r = sy;
    theta = 1 - sx / (sy * 4);
}
theta += (r < 0) ? 0.5f : 0;
r = std::abs(r);
theta *= 2 * Pi;
return Point2f(r * std::cos(theta), r * std::sin(theta));

